tasks.solution:
// triple'ı ok fonksiyonu olarak yeniden yaz, sonra isPositive'i ekle
const triple = (n) => n * 3;
const isPositive = (n) => n > 0;

console.log(triple(4));
console.log(isPositive(-2));

check.js:
assert(!/function/.test(_code), "Kodunda function kelimesi kalmamalı; ok fonksiyonu kullan.");
assert(/const\s+triple\s*=\s*\(?\s*\w+\s*\)?\s*=>/.test(_code), "triple'ı const triple = (n) => ... biçiminde yaz.");
assert(triple(4) === 12 && triple(-2) === -6 && triple(0) === 0, "triple sayının 3 katını döndürmeli.");
assert(isPositive(5) === true && isPositive(0) === false && isPositive(-3) === false, "isPositive 0'dan büyük sayılar için true, diğerleri için false döndürmeli.");

