tasks.solution:
let message = "Hız normal.";
const speed = 120;

if (speed > 100) {
  message = "Çok hızlı!";
}

console.log(message);

let fuel = 40;
// addFuel ok fonksiyonunu yaz ve iki kez 25 ile çağır
const addFuel = (amount) => {
  fuel += amount;
  return fuel;
};
addFuel(25);
addFuel(25);

console.log("Yakıt:", fuel);

check.js:
assert(message === "Çok hızlı!", "message 'Çok hızlı!' olmalı. Blok içindeki let yeni bir değişken oluşturuyor.");
assert((_code.match(/let\s+message/g) || []).length === 1, "Kodda yalnızca bir tane let message olmalı.");
assert(fuel === 90, "addFuel(25)'i iki kez çağırdıktan sonra fuel 90 olmalı.");
assert(!/fuel\s*=\s*90/.test(_code), "fuel'i elle 90 yapma; addFuel'i çağır.");
assert(addFuel(10) === 100 && fuel === 100, "addFuel dışarıdaki fuel'e eklemeli ve yeni değeri döndürmeli (addFuel(10) → 100).");

tasks.starter:
const repeat = (times, action) => {
  // action'ı 1'den times'a kadar her sayıyla çağır
};

repeat(3, (n) => console.log(`Tur ${n}`));

tasks.solution:
const repeat = (times, action) => {
  // action'ı 1'den times'a kadar her sayıyla çağır
  for (let i = 1; i <= times; i++) {
    action(i);
  }
};

repeat(3, (n) => console.log(`Tur ${n}`));

check.js:
assert(_lines.join("|") === "Tur 1|Tur 2|Tur 3", "Çıktı 'Tur 1', 'Tur 2', 'Tur 3' olmalı.");
const got = [];
repeat(4, (n) => got.push(n));
assert(same(got, [1, 2, 3, 4]), "repeat(4, ...) action'ı 1, 2, 3, 4 ile çağırmalı.");
let calls = 0;
repeat(0, () => calls++);
assert(calls === 0, "repeat(0, ...) action'ı hiç çağırmamalı.");

