challenge.solution:
function makeTank(capacity) {
  // depodaki miktarı tutan bir değişken ve onu güncelleyen bir fonksiyon
  let level = 0;
  return (amount) => {
    level = Math.min(level + amount, capacity);
    return level;
  };
}

const mainTank = makeTank(100);
console.log(mainTank(30));
console.log(mainTank(50));
console.log(mainTank(40));

check.js:
const t1 = makeTank(100);
assert(typeof t1 === "function", "makeTank bir fonksiyon döndürmeli.");
assert(t1(30) === 30 && t1(50) === 80, "Yeni bir makeTank(100) deposuna 30 ve 50 eklenince 30, sonra 80 dönmeli.");
assert(t1(40) === 100 && t1(5) === 100, "Depo kapasiteyi aşmamalı: 80 + 40 → 100.");
const t2 = makeTank(10);
assert(t2(4) === 4 && t2(4) === 8 && t2(4) === 10, "makeTank(10) ayrı bir depo olmalı ve 10'u aşmamalı.");
assert(t1(0) === 100, "İki depo birbirini etkilememeli.");

