project_task.solution:
function makeCounter(step = 1) {
  let count = 0;
  return () => {
    count += step;
    return count;
  };
}

const countStar = makeCounter();
const addScore = makeCounter(10);
let stars = 0;
let score = 0;

// 3 yıldız topla: her turda stars = countStar(); score = addScore();
for (let i = 0; i < 3; i++) {
  stars = countStar();
  score = addScore();
}

console.log(`Yıldız: ${stars} | Skor: ${score}`);

check.js:
const c1 = makeCounter();
assert(typeof c1 === "function", "makeCounter bir fonksiyon döndürmeli.");
assert(c1() === 1 && c1() === 2 && c1() === 3, "makeCounter() ile oluşan sayaç 1, 2, 3 diye saymalı.");
const c2 = makeCounter(5);
assert(c2() === 5 && c2() === 10, "makeCounter(5) ile oluşan sayaç 5, 10 diye saymalı.");
assert(c1() === 4, "Her sayaç kendi sayısını tutmalı; sayaçlar birbirini etkilememeli.");
assert(stars === 3 && score === 30, "3 yıldızdan sonra stars 3, score 30 olmalı.");
assert(!/(stars|score)\s*=\s*(3|30)\b/.test(_code), "Sayıları elle yazma; sayaçları çağır.");
assert(_lines.includes("Yıldız: 3 | Skor: 30"), "Çıktıda 'Yıldız: 3 | Skor: 30' görünmeli.");

