project_task.solution:
function makeVisitCounter(pageName) {
  let visits = 0;
  return () => {
    visits++;
    return `${pageName} sayfası ${visits} kez ziyaret edildi.`;
  };
}

const visitAbout = makeVisitCounter("Hakkımda");
const visitProjects = makeVisitCounter("Projeler");
console.log(visitAbout());
console.log(visitProjects());
console.log(visitAbout());

check.js:
assert(_lines.join("|") === "Hakkımda sayfası 1 kez ziyaret edildi.|Projeler sayfası 1 kez ziyaret edildi.|Hakkımda sayfası 2 kez ziyaret edildi.", "Çıktı sırasıyla Hakkımda 1, Projeler 1, Hakkımda 2 ziyaret satırları olmalı.");
const blog = makeVisitCounter("Blog");
assert(typeof blog === "function", "makeVisitCounter bir fonksiyon döndürmeli.");
assert(blog() === "Blog sayfası 1 kez ziyaret edildi." && blog() === "Blog sayfası 2 kez ziyaret edildi.", "makeVisitCounter(\"Blog\") ile oluşan sayaç 'Blog sayfası 1 kez ziyaret edildi.' ile başlamalı.");
assert(makeVisitCounter("Galeri")() === "Galeri sayfası 1 kez ziyaret edildi." && blog() === "Blog sayfası 3 kez ziyaret edildi.", "Her sayfanın sayacı ayrı olmalı.");

