project_task.solution:
// makePomodoro ok fonksiyonunu yaz
const makePomodoro = (minutes = 25) => {
  let rounds = 0;
  return () => {
    rounds++;
    return `Tur ${rounds} bitti: toplam ${rounds * minutes} dakika`;
  };
};

const focus = makePomodoro();
console.log(focus());
console.log(focus());

check.js:
assert(/const\s+makePomodoro\s*=/.test(_code), "makePomodoro'yu ok fonksiyonu olarak yaz: const makePomodoro = (minutes = 25) => { ... }");
assert(_lines.join("|") === "Tur 1 bitti: toplam 25 dakika|Tur 2 bitti: toplam 50 dakika", "Çıktı 'Tur 1 bitti: toplam 25 dakika' ve 'Tur 2 bitti: toplam 50 dakika' olmalı.");
const p = makePomodoro(30);
assert(p() === "Tur 1 bitti: toplam 30 dakika" && p() === "Tur 2 bitti: toplam 60 dakika" && p() === "Tur 3 bitti: toplam 90 dakika", "makePomodoro(30) ile turlar 30, 60, 90 dakika olmalı.");
assert(makePomodoro()() === "Tur 1 bitti: toplam 25 dakika", "Her makePomodoro çağrısı sıfırdan başlayan yeni bir sayaç oluşturmalı.");

