project_task.solution:
function makeScoreKeeper(points = 10) {
  let score = 0;
  return (isCorrect) => {
    if (isCorrect) {
      score += points;
    }
    return score;
  };
}

const keeper = makeScoreKeeper();
const results = [true, false, true, true];
let finalScore = 0;

// Her sonucu keeper'a gönder
for (const result of results) {
  finalScore = keeper(result);
}

console.log("Puan:", finalScore);

check.js:
const k = makeScoreKeeper();
assert(typeof k === "function", "makeScoreKeeper bir fonksiyon döndürmeli.");
assert(k(true) === 10 && k(false) === 10 && k(true) === 20, "Doğru cevapta 10 eklenmeli, yanlışta puan değişmemeli; her çağrı güncel puanı döndürmeli.");
const k5 = makeScoreKeeper(5);
assert(k5(true) === 5 && k5(true) === 10, "makeScoreKeeper(5) her doğru cevapta 5 eklemeli.");
assert(k(false) === 20, "Her puan tutucu kendi puanını tutmalı.");
assert(finalScore === 30, "finalScore 30 olmalı.");
assert(!/finalScore\s*=\s*30/.test(_code), "Puanı elle yazma; keeper'ı döngüde çağır.");
assert(_lines.includes("Puan: 30"), "Çıktıda 'Puan: 30' görünmeli.");
